package net.officefloor.hq.app.voidreason;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;
import java.util.List;
import net.officefloor.hq.app.SignedInUser;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/void-reasons")
public class VoidReasonController {

    /** A void reason as the screen shows it. */
    public record VoidReasonView(Long id, String reason) {
        static VoidReasonView of(VoidReason reason) {
            return new VoidReasonView(reason.getId(), reason.getReason());
        }
    }

    /** A void reason: its text, trimmed as it is added. */
    public record VoidReasonRequest(@NotBlank @Size(max = 255) String reason) {
    }

    private final VoidReasonService service;

    public VoidReasonController(VoidReasonService service) {
        this.service = service;
    }

    /** The sheet's void reasons, in the order they were added. */
    @GetMapping
    public List<VoidReasonView> list(@PathVariable @NotBlank @Size(max = 200) String sheetId) {
        return service.list(sheetId.trim()).stream().map(VoidReasonView::of).toList();
    }

    /** Add a void reason to the sheet. */
    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public VoidReasonView add(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Validated VoidReasonRequest request) {
        return VoidReasonView.of(service.add(sheetId.trim(), SignedInUser.decode(user), request.reason()));
    }

    /** A blank reason, or one already on the sheet's list, is refused. */
    @ExceptionHandler({VoidReasonRefusedException.class, DataIntegrityViolationException.class})
    @ResponseStatus(HttpStatus.CONFLICT)
    public void refused() {
    }

    @ExceptionHandler(HttpMessageNotReadableException.class)
    @ResponseStatus(HttpStatus.BAD_REQUEST)
    public void unreadable() {
    }
}
package net.officefloor.hq.app.voidreason;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/** A void reason on a sheet: while the sheet has any, a claim is voided with one of them. */
@Entity
@Table(name = "void_reason")
public class VoidReason {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "reason", nullable = false)
    private String reason;

    protected VoidReason() {
    }

    public VoidReason(String sheetId, String reason) {
        this.sheetId = sheetId;
        this.reason = reason;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getReason() {
        return reason;
    }
}
package net.officefloor.hq.app.voidreason;

/** A void reason that cannot be added: it is blank, or already on the sheet's list. */
public class VoidReasonRefusedException extends RuntimeException {

    public VoidReasonRefusedException(String message) {
        super(message);
    }
}
package net.officefloor.hq.app.voidreason;

import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;

public interface VoidReasonRepository extends JpaRepository<VoidReason, Long> {

    /** The sheet's void reasons, in the order they were added. */
    List<VoidReason> findBySheetIdOrderByIdAsc(String sheetId);

    /** Whether the reason is on the sheet's list. */
    boolean existsBySheetIdAndReason(String sheetId, String reason);
}
package net.officefloor.hq.app.voidreason;

import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** The void reasons on a sheet: while its list is not empty, a claim is voided with one of them. */
@Service
public class VoidReasonService {

    private final VoidReasonRepository reasons;
    private final SheetService sheets;
    private final Audit audit;

    public VoidReasonService(VoidReasonRepository reasons, SheetService sheets, Audit audit) {
        this.reasons = reasons;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The sheet's void reasons, in the order they were added. */
    public List<VoidReason> list(String sheetId) {
        return reasons.findBySheetIdOrderByIdAsc(sheetId);
    }

    /** Whether the reason is on the sheet's list. */
    public boolean listed(String sheetId, String reason) {
        return reasons.existsBySheetIdAndReason(sheetId, reason);
    }

    /** Add a reason, trimmed, to the sheet's list. Refused when it is blank or already on the list.
     *  The sheet is held locked so the same reason added at the same moment is checked against itself. */
    @Transactional
    public VoidReason add(String sheetId, String user, String reason) {
        String text = reason == null ? "" : reason.trim();
        if (text.isEmpty()) {
            throw new VoidReasonRefusedException("A void reason cannot be blank");
        }
        sheets.lock(sheetId);
        if (reasons.existsBySheetIdAndReason(sheetId, text)) {
            throw new VoidReasonRefusedException("The reason " + text + " is already on the sheet's list");
        }
        VoidReason saved = reasons.saveAndFlush(new VoidReason(sheetId, text));
        audit.recordOnCommit("VOID_REASON_ADDED sheet=" + sheetId + " by=" + user + " reason=" + text);
        return saved;
    }
}
import { HttpClient } from '@angular/common/http';
import { Component, Injectable, effect, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';

export interface VoidReason {
  id: number;
  /** The reason, trimmed; unique on the sheet, it names the reason's row. */
  reason: string;
}

// The active sheet's void reasons, in the order they were added, re-read whenever a sheet is loaded.
@Injectable({ providedIn: 'root' })
export class VoidReasonStore {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  readonly reasons = signal<VoidReason[]>([]);

  constructor() {
    effect(() => {
      const sheet = this.session.sheetId();
      const load = this.session.loads();
      this.reasons.set([]);
      if (sheet) void this.read(sheet, load);
    });
  }

  /** Add a reason to the active sheet; the server refuses a blank one or one already on its list. */
  async add(reason: string): Promise<void> {
    const sheet = this.session.sheetId();
    if (!sheet) throw new Error('No sheet loaded.');
    const saved = await firstValueFrom(
      this.http.post<VoidReason>(`/api/sheets/${encodeURIComponent(sheet)}/void-reasons`, { reason }),
    );
    if (this.session.sheetId() !== sheet) return;
    this.reasons.update((list) => [...list.filter((r) => r.id !== saved.id), saved]);
  }

  private async read(sheet: string, load: number): Promise<void> {
    const list = await firstValueFrom(
      this.http.get<VoidReason[]>(`/api/sheets/${encodeURIComponent(sheet)}/void-reasons`),
    );
    if (this.session.loads() !== load) return;
    this.reasons.set(list);
  }
}

// The sheet's void reasons, one of which a claim is voided with while the list is not empty, and the
// entry that adds one.
@Component({
  selector: 'app-void-reasons',
  template: `
    <section aria-labelledby="void-reasons-heading">
      <h2 id="void-reasons-heading">Void reasons</h2>
      <form (submit)="submit($event)">
